/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation reused a shared {@link Parser} instance and
 * configured the {@link ParserOptions} inside a synchronized block.  Because
 * the same parser could be used by other threads before the options were
 * applied, XML External Entity (XXE) attacks were still possible.</p>
 *
 * <p>This patched version creates a fresh {@link Parser} for each request,
 * configures a dedicated {@link ParserOptions} object with entity resolution
 * disabled **before** parsing, and does not rely on any synchronization.
 * The options are also hardened by disabling entity expansion and DTD
 * processing where the API provides such controls.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  Secure readFrom implementation
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        /* 1. Obtain a brand‑new parser instance.  The Abdera API guarantees that
         *    each call to {@code getParser()} returns an independent parser,
         *    eliminating cross‑thread state leakage.
         */
        Parser parser = ATOM_ENGINE.getParser();

        /* 2. Build a fresh ParserOptions object and configure it *before* any
         *    parsing occurs.  Disabling entity resolution prevents the parser
         *    from expanding external entities, which is the core of the XXE
         *    vulnerability.  Additional hardening flags are set when the API
         *    supports them.
         */
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);               // core XXE mitigation
        // The following calls are defensive – they are no‑ops if the
        // underlying implementation does not expose the feature.
        try {
            options.setExpandEntityReferences(false);    // prevent any entity expansion
        } catch (UnsupportedOperationException ignored) { }
        try {
            options.setDTDProcessing(false);             // disable DTD processing
        } catch (UnsupportedOperationException ignored) { }

        /* 3. Parse the input stream using the securely configured options.
         *    The parser instance is not shared, so no synchronization is
         *    required.
         */
        Document<T> doc = parser.parse(entityStream, options);

        /* 4. Return the root element of the parsed document. */
        return doc.getRoot();
    }

    // ----------------------------------------------------------------------
    //  Other abstract/provider methods would follow …
    // ----------------------------------------------------------------------
