import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods ...

    /**
     * Allocates a file inside {@code dir} using the supplied {@code name}.
     * The method sanitises {@code name} to prevent directory‑traversal attacks.
     *
     * @param dir  the target directory, must not be {@code null}
     * @param name the requested file name, may contain a query part after '?'
     * @return a {@link File} that does not yet exist and is guaranteed to be
     *         located inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the resulting path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Ensure the directory exists
        if (!dir.mkdirs() && !dir.isDirectory()) {
            throw new IllegalStateException("Unable to create target directory: " + dir);
        }

        // Strip any URL‑style query string (e.g. "file.txt?version=1")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Keep only the last path element – this removes any "../" or absolute
        // path components supplied by an attacker.
        String sanitized = Paths.get(name).getFileName().toString();

        // Reject names that resolve to parent‑directory references after normalisation.
        if (sanitized.contains("..")) {
            throw new SecurityException("Invalid file name containing parent‑directory reference");
        }

        // Build the initial candidate file.
        File candidate = new File(dir, sanitized);

        // Verify that the candidate really resides inside the intended directory.
        Path dirCanonical;
        Path candidateCanonical;
        try {
            dirCanonical = dir.getCanonicalFile().toPath();
            candidateCanonical = candidate.getCanonicalFile().toPath();
        } catch (IOException e) {
            throw new IllegalStateException("Failed to resolve canonical paths", e);
        }
        if (!candidateCanonical.startsWith(dirCanonical)) {
            throw new SecurityException("Resulting file would be outside the target directory");
        }

        // If a file with the same name already exists, generate a new unique name.
        int dot = sanitized.lastIndexOf('.');
        String prefix = (dot < 0) ? sanitized : sanitized.substring(0, dot);
        String suffix = (dot < 0) ? "" : sanitized.substring(dot);
        int index = 2;
        while (candidate.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            candidate = new File(dir, newName);
            try {
                candidateCanonical = candidate.getCanonicalFile().toPath();
            } catch (IOException e) {
                throw new IllegalStateException("Failed to resolve canonical path for candidate", e);
            }
            if (!candidateCanonical.startsWith(dirCanonical)) {
                // This should never happen because we only append a numeric suffix,
                // but we keep the check for completeness.
                throw new SecurityException("Generated file would be outside the target directory");
            }
        }

        // Ensure the parent directory hierarchy exists.
        File parent = candidate.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalStateException("Unable to create parent directories for: " + candidate);
        }

        return candidate;
    }

    // other methods ...

}
