     * resulting file is a descendant of {@code baseDir}.  If the validation fails,
     * an {@link IOException} is thrown.
     *
     * @param baseDir   the intended extraction directory (must be a directory)
     * @param entryName the raw entry name from the archive
     * @return a {@link File} that is safely inside {@code baseDir}
     * @throws IOException if the resolved path escapes {@code baseDir}
     */
    private static File resolveAndValidateTarget(final File baseDir, final String entryName) throws IOException {
        // Resolve using Plexus' utility (preserves any platform‑specific handling)
        File resolved = FileUtils.resolveFile(baseDir, entryName);

        // Canonicalise both paths to eliminate "..", symbolic links, etc.
        String baseCanonical = baseDir.getCanonicalPath();
        String resolvedCanonical = resolved.getCanonicalPath();

        // Ensure the resolved path starts with the base directory path followed by a separator.
        // Equality is also allowed when the entry itself resolves to the base directory.
        if (!resolvedCanonical.equals(baseCanonical) &&
            !resolvedCanonical.startsWith(baseCanonical + File.separator)) {
            throw new IOException("Entry '" + entryName + "' is outside of the target directory");
        }

        return resolved;
    }

