     * directory.  The check is deliberately strict: absolute paths and any path containing
     * parent‑directory references are rejected.
     *
     * @param baseDir            the extraction root directory
     * @param symlinkDestination the raw destination string from the archive
     * @throws IOException if the destination is considered unsafe
     */
    private static void validateSymlinkDestination(final File baseDir, final String symlinkDestination) throws IOException {
        // Reject absolute paths – they would place the link outside the extraction tree
        File destFile = new File(symlinkDestination);
        if (destFile.isAbsolute()) {
            throw new IOException("Symlink destination must be relative: " + symlinkDestination);
        }

        // Reject any parent‑directory traversal components
        if (symlinkDestination.contains("..") || symlinkDestination.contains("./") || symlinkDestination.contains("\\..")) {
            throw new IOException("Symlink destination contains unsafe path elements: " + symlinkDestination);
        }

        // Resolve the destination relative to the extraction directory and ensure it stays inside.
        File resolvedDest = new File(baseDir, symlinkDestination);
        String baseCanonical = baseDir.getCanonicalPath();
        String destCanonical = resolvedDest.getCanonicalPath();

        if (!destCanonical.equals(baseCanonical) && !destCanonical.startsWith(baseCanonical + File.separator)) {
            throw new IOException("Symlink destination resolves outside of the target directory: " + symlinkDestination);
        }
    }

    // ----------------------------------------------------------------------
    // Existing getters (unchanged)
    // ----------------------------------------------------------------------
    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }

    // other methods …
}
