import java.util.BitSet;
import javax.ws.rs.ext.RuntimeDelegate;

/**
 * Header delegate for {@code MediaType}. The implementation validates the
 * {@code type} and {@code subtype} components of a media type string.
 *
 * <p>The original implementation only checked for a few disallowed characters,
 * which allowed CR/LF and other control characters to slip through, opening the
 * door to HTTP header injection attacks.  This patched version follows the
 * RFC‑7230 definition of a <em>token</em> (the allowed characters for a media
 * type token) and uses a whitelist approach: only characters that are explicitly
 * permitted are accepted.  All control characters, whitespace, and any other
 * separator characters are rejected.</p>
 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // -----------------------------------------------------------------------
    // Token validation (RFC 7230, section 3.2.6)
    // -----------------------------------------------------------------------
    /**
     * BitSet containing all characters that are allowed in a media type token.
     * The set includes the characters defined by RFC‑7230 as {@code tchar}
     * plus the asterisk {@code '*'} which is used for wild‑cards.
     */
    private static final BitSet VALID_TOKEN_CHARS = new BitSet(128);
    static {
        // ALPHA
        for (char c = 'a'; c <= 'z'; c++) {
            VALID_TOKEN_CHARS.set(c);
        }
        for (char c = 'A'; c <= 'Z'; c++) {
            VALID_TOKEN_CHARS.set(c);
        }
        // DIGIT
        for (char c = '0'; c <= '9'; c++) {
            VALID_TOKEN_CHARS.set(c);
        }
        // tchar symbols
        char[] symbols = {
                '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^',
                '_', '`', '|', '~', '*'
        };
        for (char c : symbols) {
            VALID_TOKEN_CHARS.set(c);
        }
        // The asterisk is also used as a wildcard in media types.
        VALID_TOKEN_CHARS.set('*');
    }

    /**
     * Validates that the supplied string consists solely of characters that are
     * permitted in a media type token.  The method returns {@code false} for
     * {@code null}, empty strings, control characters (including CR/LF), spaces,
     * or any character not present in {@link #VALID_TOKEN_CHARS}.
     *
     * @param str the string to validate
     * @return {@code true} if the string is a valid token, {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);

            // Reject any control characters (including CR '\r' and LF '\n')
            if (ch <= 0x1F || ch == 0x7F) {
                return false;
            }

            // Reject any character outside the ASCII range (tokens are defined as ASCII)
            if (ch >= VALID_TOKEN_CHARS.size()) {
                return false;
            }

            // Finally, ensure the character is part of the whitelist
            if (!VALID_TOKEN_CHARS.get(ch)) {
                return false;
            }
        }
        return true;
    }

    // -----------------------------------------------------------------------
    // Other methods of the delegate (omitted for brevity)
    // -----------------------------------------------------------------------
}
