private void validateSignature(Object signedObject, Signature signature) throws WSSecurityException {
    if (signature == null) {
        LOG.fine("Missing signature");
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    // Verify reference URI
    if (signature.getSignedInfo() == null || signature.getSignedInfo().getReferences().isEmpty()) {
        LOG.fine("Signature does not contain any references");
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    String expectedUri = "#" + getId(signedObject);
    String actualUri = signature.getSignedInfo().getReferences().get(0).getURI();
    if (!expectedUri.equals(actualUri)) {
        LOG.fine("Signature reference URI does not match signed element ID");
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    try {
        if (verificationCredential == null) {
            LOG.fine("Verification credential not configured");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }
        SignatureValidator.validate(signature, verificationCredential);
    } catch (SignatureException e) {
        LOG.fine("Signature validation failed: " + e.getMessage());
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity", e);
    }
}

private String getId(Object obj) {
    if (obj instanceof org.opensaml.saml.saml2.core.Response) {
        return ((org.opensaml.saml.saml2.core.Response) obj).getID();
    } else if (obj instanceof org.opensaml.saml.saml2.core.Assertion) {
        return ((org.opensaml.saml.saml2.core.Assertion) obj).getID();
    }
    return null;
}

