import java.util.Date;
import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

import org.w3c.dom.Element;

import org.apache.cxf.common.logging.LogUtils;
import org.apache.wss4j.common.ext.WSSecurityException;
import org.apache.wss4j.common.util.DOM2Writer;
import org.opensaml.saml.saml2.core.AuthnStatement;
import org.opensaml.saml.saml2.core.Assertion;
import org.opensaml.saml.saml2.core.Response;
import org.opensaml.saml.saml2.core.Subject;
import org.opensaml.security.credential.Credential;
import org.opensaml.xmlsec.signature.Signature;
import org.opensaml.xmlsec.signature.support.SignatureException;
import org.opensaml.xmlsec.signature.support.SignatureValidator;

/**
 * Validator for SAML 2.0 SSO responses.
 *
 * <p>This implementation mitigates XML wrapping attacks by:
 * <ul>
 *   <li>Enforcing that the {@code Destination} attribute always matches the
 *       configured Assertion Consumer Service URL.</li>
 *   <li>Validating the XML Signature on the {@code Response} (if present) and
 *       on each {@code Assertion} that is required to be signed.</li>
 *   <li>Ensuring the signature reference URI points to the element's ID,
 *       preventing an attacker from inserting unsigned sibling elements.</li>
 *   <li>Detecting duplicate Assertion IDs, which are a common vector for
 *       wrapping attacks.</li>
 *   <li>Requiring a verification {@link Credential} to be supplied; without it
 *       the validator will reject the response.</li>
 * </ul>
 *
 * The class is compatible with Java 8 and OpenSAML 3.
 */
public class SAMLSSOResponseValidator {

    private static final Logger LOG = LogUtils.getL7dLogger(SAMLSSOResponseValidator.class);

    private String assertionConsumerURL;
    private boolean enforceAssertionsSigned = true;

    /** Credential used to verify XML signatures (must be configured by the caller). */
    private Credential verificationCredential;

    /** Setter for the verification credential. */
    public void setVerificationCredential(Credential credential) {
        this.verificationCredential = credential;
    }

    // -----------------------------------------------------------------------
    // Core validation logic
    // -----------------------------------------------------------------------

    /**
     * Validate a SAML 2 Protocol Response.
     *
     * @param samlResponse the response to validate
     * @param postBinding  true if the response was delivered using HTTP POST binding
     * @return a {@link SSOValidatorResponse} containing useful data extracted from the response
     * @throws WSSecurityException if validation fails
     */
    public SSOValidatorResponse validateSamlResponse(Response samlResponse, boolean postBinding)
            throws WSSecurityException {

        /* --------------------------------------------------------------------
         * 1. Basic structural checks
         * -------------------------------------------------------------------- */
        validateIssuer(samlResponse.getIssuer());

        // Destination must always match the configured ACS URL.
        String destination = samlResponse.getDestination();
        if (destination == null || !destination.equals(assertionConsumerURL)) {
            LOG.fine("The Response destination does not match the Assertion Consumer Service URL");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        // At least one Assertion is required.
        if (samlResponse.getAssertions() == null || samlResponse.getAssertions().isEmpty()) {
            LOG.fine("The Response must contain at least one Assertion");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        // --------------------------------------------------------------------
        // 2. Verify the Response signature (if present)
        // --------------------------------------------------------------------
        if (samlResponse.isSigned()) {
            Signature responseSignature = samlResponse.getSignature();
            validateSignature(samlResponse, responseSignature);
        } else if (enforceAssertionsSigned && postBinding) {
            // When the response itself is not signed we will enforce that each
            // Assertion is signed later (see the loop below).
        }

        // --------------------------------------------------------------------
        // 3. Process each Assertion
        // --------------------------------------------------------------------
        Set<String> assertionIds = new HashSet<>();
        boolean foundValidSubject = false;
        Date sessionNotOnOrAfter = null;

        for (Assertion assertion : samlResponse.getAssertions()) {

            // ---- 3.1 Assertion ID uniqueness ---------------------------------
            String assertionId = assertion.getID();
            if (assertionId == null || assertionId.isEmpty()) {
                LOG.fine("Assertion ID must be present");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }
            if (!assertionIds.add(assertionId)) {
                LOG.fine("Duplicate Assertion ID detected: " + assertionId);
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }

            // ---- 3.2 Issuer validation --------------------------------------
            if (assertion.getIssuer() == null) {
                LOG.fine("Assertion Issuer must not be null");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }
            validateIssuer(assertion.getIssuer());

            // ---- 3.3 Signature validation --------------------------------------
            if (assertion.getSignature() != null) {
                validateSignature(assertion, assertion.getSignature());
            } else if (enforceAssertionsSigned && postBinding) {
                LOG.fine("Assertions must be signed when using HTTP POST binding");
                throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
            }

            // ---- 3.4 Authentication statements ---------------------------------
            if (assertion.getAuthnStatements() != null && !assertion.getAuthnStatements().isEmpty()) {
                Subject subject = assertion.getSubject();
                if (validateAuthenticationSubject(subject, assertionId, postBinding)) {
                    validateAudienceRestrictionCondition(assertion.getConditions());
                    foundValidSubject = true;
                    for (AuthnStatement authnStatement : assertion.getAuthnStatements()) {
                        if (authnStatement.getSessionNotOnOrAfter() != null) {
                            sessionNotOnOrAfter = authnStatement.getSessionNotOnOrAfter().toDate();
                        }
                    }
                }
            }
        }

        // --------------------------------------------------------------------
        // 4. Ensure at least one valid Subject was found
        // --------------------------------------------------------------------
        if (!foundValidSubject) {
            LOG.fine("The Response did not contain any Authentication Statement that matched the Subject Confirmation criteria");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        // --------------------------------------------------------------------
        // 5. Build the successful validation response
        // --------------------------------------------------------------------
        SSOValidatorResponse validatorResponse = new SSOValidatorResponse();
        validatorResponse.setResponseId(samlResponse.getID());
        validatorResponse.setSessionNotOnOrAfter(sessionNotOnOrAfter);
        if (samlResponse.getIssueInstant() != null) {
            validatorResponse.setCreated(samlResponse.getIssueInstant().toDate());
        }

        // Clone the first Assertion's DOM element for downstream processing.
        Element assertionElement = samlResponse.getAssertions().get(0).getDOM();
        Element clonedAssertionElement = (Element) assertionElement.cloneNode(true);
        validatorResponse.setAssertionElement(clonedAssertionElement);
        validatorResponse.setAssertion(DOM2Writer.nodeToString(clonedAssertionElement));

        return validatorResponse;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Validates an XML Signature.
     *
     * @param signedObject the SAML object that carries the signature (Response or Assertion)
     * @param signature    the signature to validate
     * @throws WSSecurityException if the signature is missing, malformed, or fails validation
     */
    private void validateSignature(Object signedObject, Signature signature) throws WSSecurityException {
        if (signature == null) {
            LOG.fine("Missing XML Signature");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
