public String getForwardPage(HttpServletRequest request) {
    String pathInfo = request.getPathInfo();
    if (pathInfo == null) {
        return DEFAULT_PAGE;
    }
    // Decode
    try {
        pathInfo = URLDecoder.decode(pathInfo, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        // UTF-8 always supported
    }
    // Remove leading slash
    if (pathInfo.startsWith("/")) {
        pathInfo = pathInfo.substring(1);
    }
    // Normalize path to eliminate ../ sequences
    Path normalizedPath = Paths.get(pathInfo).normalize();
    String normalized = normalizedPath.toString();

    // Reject traversal attempts
    if (normalized.contains("..") || normalized.startsWith("/") || normalizedPath.isAbsolute()) {
        return DEFAULT_PAGE;
    }

    // Whitelist check
    if (!ALLOWED_PAGES.contains(normalized)) {
        return DEFAULT_PAGE;
    }

    return normalized;
}

