        ByteBuffer out = ByteBuffer.allocate(
                estimateInitialBufferSize(enc, cb.remaining()));

        // Stall‑detection variables – they ensure that the loop makes forward
        // progress.  If the position does not change for a few iterations we
        // abort to prevent an infinite loop (possible DoS vector).
        int lastPosition = -1;
        int stallCount = 0;
        final int MAX_STALL = 5;   // arbitrary safe limit

        while (cb.remaining() > 0) {
            final CoderResult res = enc.encode(cb, out, false);

            // -----------------------------------------------------------------
            // 1) Unmappable / malformed input – replace the offending character(s)
            //    with a surrogate representation (as the original code intended).
            // -----------------------------------------------------------------
