                // Ensure enough space for the surrogate representation (6 bytes per
                // problematic character, as used by the original logic).
                int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
                if (needed > out.remaining()) {
                    // Grow the buffer just enough to hold the replacement bytes.
                    out = ZipEncodingHelper.growBufferBy(out, needed - out.remaining());
                }

                // Allocate a temporary CharBuffer for the surrogate conversion once.
                if (tmp == null) {
                    tmp = CharBuffer.allocate(6);
                }

                // Replace each problematic character individually.
                for (int i = 0; i < res.length(); ++i) {
                    // cb.get() advances the CharBuffer position, guaranteeing progress.
                    char ch = cb.get();
                    out = encodeFully(enc, encodeSurrogate(tmp, ch), out);
