import java.util.Calendar;
import java.util.logging.Logger;
import static java.util.Calendar.*;

public final class CronTab {

    /** Logger used for diagnostics – helps to spot unexpected looping behaviour. */
    private static final Logger LOGGER = Logger.getLogger(CronTab.class.getName());

    /** Upper bound on the number of iterations the ceil‑adjustment loop may perform.
     *  The value is deliberately generous (covers all realistic cron expressions) but
     *  low enough to guarantee termination even if the adjustment logic is buggy. */
    private static final int MAX_ITERATIONS = 1_000;

    // other methods …

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it
     *         indicates an impossible (e.g. Jun 31) date, or at least a date too rare to be useful.
     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar and set a hard limit two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        int iteration = 0;                     // counts loop passes
        Calendar previousState = null;         // remembers the calendar from the previous pass

        OUTER:
        while (true) {
            // -----------------------------------------------------------------
            // 1️⃣  Guard against pathological infinite loops.
            // -----------------------------------------------------------------
            if (++iteration > MAX_ITERATIONS) {
                LOGGER.warning("Ceil loop exceeded max iterations (" + MAX_ITERATIONS + "); possible infinite loop.");
                throw new RareOrImpossibleDateException();
            }

            // If we have already passed the two‑year horizon, give up.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // Detect a situation where no progress is made between iterations.
            if (previousState != null && cal.equals(previousState)) {
                LOGGER.warning("Ceil loop made no progress on iteration " + iteration + "; aborting.");
                throw new RareOrImpossibleDateException();
            }
            previousState = (Calendar) cal.clone();

            // -----------------------------------------------------------------
            // 2️⃣  Adjust fields according to the cron definition.
            // -----------------------------------------------------------------
            for (CalendarField f : CalendarField.ADJUST_ORDER) {
                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // Field already at its ceiling – nothing to do.
                if (cur == next) {
                    continue;
                }

                // Reset all less‑significant fields because a higher field changed.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // -------------------------------------------------------------
                // 2a.  The field cannot be satisfied – roll it up and start over.
                // -------------------------------------------------------------
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    // Restart the outer loop so that higher fields are re‑evaluated.
                    continue OUTER;
                }

                // -------------------------------------------------------------
                // 2b.  Normal case – set the field to the next valid value.
                // -------------------------------------------------------------
                f.setTo(cal, next);

                // Some fields (e.g., day‑of‑month) may require a full re‑evaluation
                // after being modified because they affect other fields.
                if (f.redoAdjustmentIfModified) {
                    continue OUTER;
                }
            }

            // All fields are now consistent – return the adjusted calendar.
            return cal;
        }
    }

    // other methods …
}
