        Class<?> type = getDocumentType();
        Exception cause = null;

        // First, try the generic type conversion that Camel provides.
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e; // remember the conversion failure for later
            }
        }

        // If conversion did not succeed, handle the known body types manually.
        if (answer == null) {
