public boolean isAllowed(HttpServletRequest request) throws IOException {
    // get authenticated user id
    String authUserId = null;
    Principal principal = request.getUserPrincipal();
    if (principal != null) {
        authUserId = principal.getName();
    } else {
        // fallback to attribute
        Object attr = request.getAttribute("user_id");
        if (attr != null) {
            authUserId = attr.toString();
        }
    }

    // if cannot determine, deny
    if (authUserId == null) {
        return false;
    }

    // extract target id from URL
    String targetId = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX, UaaUrlUtils.getRequestPath(request));

    // enforce that the authenticated user is the same as target id
    if (!authUserId.equals(targetId)) {
